function mod:BirthrightDesc()
	if EID then
		local EsauName = EID:getDescriptionEntry("birthright", PlayerType.PLAYER_ESAU+1)[1] or "Esau"
		for k,v in pairs(mod.EBEIDDesc) do
			local JandE_EID = mod.EBEIDDesc[k][20][mod.MCMOption.Settings["Jacob"]].."#{{Player"..PlayerType.PLAYER_ESAU.."}} {{ColorGray}}"..EsauName.."#"..mod.EBEIDDesc[k][20][mod.MCMOption.Settings["Esau"]]
			for i = 1, #mod.MCMOption.PlayerType do
				local ptype = mod.GetMCMValue(i-1)
				if (i < 39 or i > 41) and i ~= 20 and ptype then
					EID:addBirthright(i-1, mod.EBEIDDesc[k][i][ptype], EID:getDescriptionEntry("birthright", mod.MCMOption.PlayerType[i]+1)[1] or mod.GetMCMName(i-1), mod.Languages[k])
				end
			end

			EID:addBirthright(PlayerType.PLAYER_JACOB, JandE_EID, EID:getDescriptionEntry("birthright", PlayerType.PLAYER_JACOB+1)[1] or "Jacob", mod.Languages[k])
			EID:addBirthright(PlayerType.PLAYER_LAZARUS2_B, mod.EBEIDDesc[k][39][mod.MCMOption.Settings["Tainted Lazarus"]], EID:getDescriptionEntry("birthright", PlayerType.PLAYER_LAZARUS_B+1)[1] or "Lazarus", mod.Languages[k])
			EID:addBirthright(PlayerType.PLAYER_THESOUL_B, mod.EBEIDDesc[k][41][mod.MCMOption.Settings["Tainted Forgotten"]], EID:getDescriptionEntry("birthright", PlayerType.PLAYER_THESOUL_B+1)[1] or "The Soul", mod.Languages[k])
			EID:addBirthright(PlayerType.PLAYER_JACOB2_B, mod.EBEIDDesc[k][40][mod.MCMOption.Settings["Tainted Jacob"]], EID:getDescriptionEntry("birthright", PlayerType.PLAYER_JACOB2_B+1)[1] or "Jacob", mod.Languages[k])

			local strings = {}
			for _,player in ipairs(mod:GetPlayers()) do
				local playerID = player:GetPlayerType()
				local ptype = mod.GetMCMValue(playerID)
				if ptype then
					local i,j = 1,2
					i,j = playerID+1,ptype
					local birthrightDesc = EID:getDescriptionEntry("birthright", playerID+1)
					local playerName = birthrightDesc[1] or player:GetName()
					local icon = EID:getIcon("Player"..playerID) ~= EID.InlineIcons["ERROR"] and "{{Player"..playerID.."}}" or "{{CustomTransformation}}"
					strings[i] = "#"..icon.." {{ColorGray}}"..playerName.."{{CR}}#"..v[i][j]
				end
			end
			local longStrings = ""
			for i = 1, #mod.MCMOption.Name do
				if strings[i] then
					longStrings = longStrings..strings[i]
				end
			end
			EID:addCollectible(substituteBirthright, longStrings,"Birthright", mod.Languages[k])
		end
	end
end